INSERT INTO `movies` (`movie_id`, `title`, `age_rating`, `duration`, `trailer`, `description`, `archived`) VALUES
(2, 'Avatar: Istota wody', '12', 193, 'https://www.youtube.com/watch?reload=9&v=0fHz-X9fQoM', 'Akcja filmu Avatar: Istota wody rozgrywa się ponad dziesięć lat po wydarzeniach z pierwszej części. To opowieść o rodzinie Jake’a i Neytiri oraz ich staraniach, by zapewnić bezpieczeństwo sobie i swoim dzieciom, mimo tragedii, których wspólnie doświadczają i bitew, które muszą stoczyć, aby przeżyć.* Drodzy widzowie w filmie Avatar: Istota wody znajduje się kilka scen z dynamicznymi efektami świetlnymi, które mogą powodować dyskomfort u widzów wrażliwych na światło i wpływać na osoby z epilepsją fotogenną.', 1),
(3, 'Dzika Noc', '16', 112, 'https://www.youtube.com/watch?v=nbPBgbBfXS4', 'Producenci filmów ”Nikt”, „John Wick”, „Deadpool 2” realizują dla studia Universal mroczny thriller „Dzika Noc”.\r\nZobaczymy między innymi gwiazdę serialu \"Stranger Things” Davida Harboura oraz zdobywcę nagrody Emmy- Johnego Leguizamo oraz innych: Edi Pattersona, Cam Gigandet Alexa Hassella i Beverly D\'\'Angelo.\r\nFilm wyreżyserowany będzie przez norweskiego reżysera Tommy\'\'ego Wirkolę (\"Hansel & Gretel: Łowca czarownic” na podstawie scenariusza Pata Caseya i Josha Millera (Sonic 2.Szybki jak błyskawica).\r\nKiedy pewna, bogata rodzina zostaje zakładnikami w Wigilię, przestępcy nie są przygotowani na niespodziewanego bojownika. Święty Mikołaj (w tej roli David Harbour, serial Stranger Things) jest na miejscu i ma zamiar pokazać, dlaczego Mikołaj nie będzie taki święty.', 1),
(4, 'Kot w butach: Ostatnie życzenie', '3', 100, 'https://www.youtube.com/watch?v=mGmNFtrIK-8', 'Kot w Butach wyrusza w podróż, aby odnaleźć mityczne \"ostatnie życzenie\", dzięki któremu odzyska swoje dziewięć żyć.', 1),
(5, 'Deadpool and Wolverine', '16', 127, 'https://www.youtube.com/watch?v=73_1biulkYk', 'Nieodpowiedzialny bohater Deadpool odmieni historię MCU razem z Wolverinem?', 0),
(13, 'Spider Man: Poprzez multiwersum', '7', 140, 'https://www.youtube.com/watch?v=ClgCkFEmbjU', 'Z Brooklynu Miles trafia do multiwersum. Razem z Gwen Stacy, spotykają innych Spider-Manów, którzy mają za zadanie ochronę świata przed zagrożeniami. Kiedy bohaterowie spierają się o to, jak poradzić sobie z nowymi niebezpieczeństwami, Miles musi na nowo zdefiniować, co to znaczy być bohaterem i jak ocalić ludzi, których kocha.', 0),
(14, 'Spirited Away: W krainie bogów', '7', 125, 'https://www.youtube.com/watch?v=ByXuk9QqQkk', 'Rodzina Chihiro musi przeprowadzić się do nowego domu. Po drodze gubią się w lesie i trafiają do dziwnego miejsca przypominającego opuszczone wesołe miasteczko. Rodzice Chihiro znajdują stół pełen znakomitych potraw i natychmiast zabierają się do jedzenia. Tymczasem dziewczynka zwiedza to dziwne miejsce. Okazuje się ono nie opuszczonym wesołym miasteczkiem, ale tajemniczą krainą, gdzie rządzi zła czarownica, Yubaba. Aby nie podzielić losu swoich rodziców oraz uratować siebie i ich (zostali zamienieni w świnie za zjedzenie pokarmu bogów), Chihiro musi rozpocząć pracę w tym tajemniczym świecie...', 0);

